#!/usr/bin/env node
/**
 * Reads all .qmd essay and signal files and writes scripts/content-bundle.js
 * which the ingest Worker imports directly.
 *
 * Run before deploying the ingest Worker:
 *   node scripts/build-content-bundle.js
 */

import { readFileSync, readdirSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dir  = dirname(fileURLToPath(import.meta.url));
const root   = join(__dir, '..');

const SOURCES = [
  { dir: join(root, '../wh-essays/essays'),  type: 'essay',  urlPrefix: 'https://wayward.house/essays/' },
  { dir: join(root, '../wh-signals/signals'), type: 'signal', urlPrefix: 'https://wayward.house/signals/' },
];

const items = [];

for (const { dir, type, urlPrefix } of SOURCES) {
  const files = readdirSync(dir).filter(f => f.endsWith('.qmd') && f !== 'index.qmd');
  for (const file of files) {
    const slug = file.replace('.qmd', '');
    const raw  = readFileSync(join(dir, file), 'utf8');
    items.push({ type, slug, url: urlPrefix + slug, raw });
    process.stdout.write(`  ${type}/${slug}\n`);
  }
}

const output = `// Auto-generated by scripts/build-content-bundle.js — do not edit.
export const content = ${JSON.stringify(items, null, 0)};
`;

writeFileSync(join(__dir, 'content-bundle.js'), output);
console.log(`\nWrote ${items.length} items to scripts/content-bundle.js`);
